  ja: { visualTrackingSpeedTest: { title: "動体視力テスト", subtitle: "動く標的 · 視覚追跡", caption: "動く標的を目で追い、速度の変化に合わせてクリックし、難しくなっても正確さを保ちます。", rotate: "横向きにすると、広い視覚追跡フィールドで練習できます。", score: "スコア", time: "時間", timeLeft: "残り時間", level: "レベル", bestScore: "ベストスコア", getReady: "準備してください", accuracy: "命中率", avgReaction: "平均反応", peakLevel: "最高レベル", maxCombo: "最大コンボ", missFlash: "ミス表示の切替", sound: "サウンドの切替", rules: "練習方法とスコアの仕組み", about: "動体視力テストについて", aboutHeading: "この動く標的テストは何を測りますか？", aboutP1: "このブラウザ練習では、速度や方向が変わる標的を見つけてクリックします。視覚追跡、標的の予測、ポインター操作、捕捉のタイミングを一つの課題で使います。", aboutP2: "スコアは臨床的な視力検査の値ではなく、この課題で得た結果です。画面更新、フレーム処理、ブラウザ、入力機器、標的の大きさと表示時間、判断が影響します。", audience: "どんな人に向いていますか？", audienceText: "動く標的への注意と目と手のタイミングを、短いブラウザ練習で鍛えたいゲーマーや競技者向けです。", pursuit: "動く標的を追う", pursuitText: "予測した一点を凝視せず、標的を視野に保ちながら軌道の変化を見ます。", intercept: "捕捉のコントロール", interceptText: "ポインターを軌道に合わせ、安定して操作できる位置でクリックします。", shareTitle: "動体視力テスト — スコア", shareText: "動く標的の動体視力テストで {score} 点でした。記録を超えられますか？", ruleItems: [{ title: "動く標的を捕捉", detail: "+100点", badge: "コンボ × レベル（+0.6秒）", penaltyDetail: "+100点", penaltyBadge: "コンボ × レベル（+0.6秒）" }, { title: "コンボと動きの負荷", detail: "最大3.0倍", badge: "速度と反射の負荷が上がる", penaltyDetail: "最大3.0倍", penaltyBadge: "速度と反射の負荷が上がる" }, { title: "レベル進行", detail: "継続的に難化", badge: "標的が加速・縮小", penaltyDetail: "継続的に難化", penaltyBadge: "標的が加速・縮小" }, { title: "ミスと時間切れ", detail: "標準は時間ペナルティなし", badge: "コンボ解除", penaltyDetail: "−0.8秒ペナルティ", penaltyBadge: "コンボ解除" }] } },
